const TABLES:[(&str,usize);5]=[("epw_document",8),("epw_location",10),("epw_data_periods",2),("epw_data_period",7),("epw_record",38)];
fn refusal(kind:ValueRefusalKind,message:&str)->ValueError{ValueError::new(kind,message)}
pub(super) fn extent(limits:SqliteDatabaseLimits)->Result<(),ValueError>{
 let mut bytes=0usize;for statement in EpwSnapshot::SQLITE_SCHEMA.split(';'){bytes=bytes.checked_add(statement.trim().len()).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"EPW authored schema byte count overflow"))?;}for(name,_)in TABLES{bytes=bytes.checked_add(name.len()).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"EPW authored schema name count overflow"))?;}
 if bytes.max(EpwSnapshot::SQLITE_SCHEMA.len())>limits.max_schema_bytes{return Err(refusal(ValueRefusalKind::OwnershipLimit,"EPW authored schema exceeds caller bytes"))}if limits.max_tables<TABLES.len()||TABLES.iter().any(|(_,width)|*width>limits.max_columns)||limits.max_rows<3{return Err(refusal(ValueRefusalKind::WorkLimit,"EPW authored relational extent exceeds caller limits"))}Ok(())
}
pub(super) fn typed(snapshot:&EpwSnapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{extent(control.limits())?;let mut writer=RowWriter::borrowed(control,phase)?;super::visit_rows(snapshot,&mut writer)?;writer.finish_borrowed()}
fn record(value:&F,count:usize)->Result<&RecordValue,ValueError>{let F::Record(record)=value else{return Err(refusal(ValueRefusalKind::InvalidValue,"EPW literal Record required"))};if record.fields.len()!=count{return Err(refusal(ValueRefusalKind::InvalidValue,"EPW native Record has undeclared fields"))}Ok(record)}
fn field(record:&RecordValue,id:u16)->Result<&F,ValueError>{record.get(id).ok_or_else(||refusal(ValueRefusalKind::InvalidValue,"EPW native authored field is missing"))}
fn list(value:&F)->Result<&[F],ValueError>{match value{F::List(values)=>Ok(values),_=>Err(refusal(ValueRefusalKind::InvalidValue,"EPW literal List required"))}}
fn text<'a>(value:&'a F,native:&mut NativeDecodeControl<'_>)->Result<&'a str,ValueError>{let F::Text(value)=value else{return Err(refusal(ValueRefusalKind::InvalidValue,"EPW lexical field requires Text"))};native.scoped_stage(|native|{native.begin_stage(value.len())?;for part in value.as_bytes().chunks(256){native.advance(part.len())?;}Ok::<_,ValueError>(())})?;Ok(value)}
fn add(bytes:&mut usize,amount:usize,maximum:usize)->Result<(),ValueError>{*bytes=bytes.checked_add(amount).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"EPW semantic value byte count overflow"))?;if *bytes>maximum{return Err(refusal(ValueRefusalKind::OwnershipLimit,"EPW semantic cells exceed caller bytes"))}Ok(())}
fn row(record:&RecordValue,ids:impl IntoIterator<Item=u16>,base:usize,bytes:&mut usize,maximum:usize,native:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{add(bytes,base,maximum)?;for id in ids{add(bytes,text(field(record,id)?,native)?.len(),maximum)?;}native.step()}
pub(super) fn borrowed(root:&RecordValue,limits:SqliteDatabaseLimits,native:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{
 extent(limits)?;if root.fields.len()!=10{return Err(refusal(ValueRefusalKind::InvalidValue,"EPW native root requires ten authored fields"))}let location=record(field(root,1)?,9)?;let header=record(field(root,8)?,2)?;let periods=list(field(header,1)?)?;let records=list(field(root,9)?)?;
 let rows=3usize.checked_add(periods.len()).and_then(|sum|sum.checked_add(records.len())).ok_or_else(||refusal(ValueRefusalKind::WorkLimit,"EPW semantic row count overflow"))?;if rows>limits.max_rows{return Err(refusal(ValueRefusalKind::WorkLimit,"EPW semantic rows exceed caller limit"))}
 if !matches!(field(header,0)?,F::UInt(value)if *value<=u64::from(u32::MAX)){return Err(refusal(ValueRefusalKind::InvalidValue,"EPW records per hour requires unsigned32"))}native.begin_stage(rows)?;let mut bytes=0;row(root,[0,2,3,4,5,6,7],8,&mut bytes,limits.max_value_bytes,native)?;row(location,0..9,8,&mut bytes,limits.max_value_bytes,native)?;add(&mut bytes,16,limits.max_value_bytes)?;native.step()?;
 for period in periods{row(record(period,4)?,0..4,24,&mut bytes,limits.max_value_bytes,native)?;}for value in records{row(record(value,35)?,0..35,24,&mut bytes,limits.max_value_bytes,native)?;}native.checkpoint()
}
